# Canonical Progress read-model endpoints (Progress Redesign PR2–PR5).
_PROGRESS_SUMMARY_PATH = "/api/progress/summary"
_PROGRESS_AXIS_INSIGHTS_PATH = "/api/progress/axis-insights"
_PROGRESS_PHYSIQUE_PATH = "/api/progress/physique"
_PROGRESS_HISTORY_PATH = "/api/progress/history"
_PROGRESS_PRIVATE_PATHS = frozenset({
    _PROGRESS_SUMMARY_PATH,
    _PROGRESS_AXIS_INSIGHTS_PATH,
    _PROGRESS_PHYSIQUE_PATH,
    _PROGRESS_HISTORY_PATH,
})


@bp.after_request
def _progress_summary_private_no_store(response):
    """Per-user trajectory/advice must not be stored by a shared cache or bfcache."""
    if request.path in _PROGRESS_PRIVATE_PATHS:
        response.headers["Cache-Control"] = "private, no-store"
    return response


def _progress_summary_error_class(error):
    """Coarse, PII-free bucket for the failure log line (never the message).

    Shared by both canonical Progress read models: PR3's
    ``UnknownCanonicalVocabulary`` is the same class of fault as PR2's
    ``UnknownProgressionSignal`` — an upstream contract moved — so it buckets
    the same way rather than inventing a competing observability vocabulary.
    """
    if isinstance(error, (
            UnknownProgressionSignal,
            UnknownCanonicalVocabulary,
            UnknownPhysiqueComparability,
    )):
        return "contract_drift"
    if isinstance(error, SQLAlchemyError):
        return "upstream_error"
    return "unexpected_error"


def _parse_weight(value):
    if value in (None, ""):
        return None, "route.weight_required"
    try:
        weight = float(value)
    except OverflowError:
        return None, "route.weight_range"
    except (TypeError, ValueError):
        return None, "route.weight_numeric"
    if not math.isfinite(weight) or not 20 <= weight <= 500:
        return None, "route.weight_range"
    return weight, None


@bp.route("/")
@require_auth
def home():
    """The canonical Today surface - the app's single home hierarchy.

    UX-2 PR4 retired the legacy `index.html` dashboard and the flag that chose
    between the two: Today is now the one production Home, and the canonical
    facts it needs (active plan, today's workout state, today's action, today's
    plan summary) are read server-side through the shared read-only helpers - the
    SAME source `/training-plan/active`, `/workout/status` and `GET /api/v1/today`
    use - then mapped by the pure presenter. Nothing on this page decides state.
    """
    if not current_user.profile_complete:
        return redirect(url_for("profile.setup"))
    today_view = build_today_view(gather_today_facts(current_user.id))
    return render_template("today.html",
        username=current_user.username,
        profile_picture=current_user.avatar_src,
        # The server's canonical Istanbul day. The page formats it for the
        # locale; the browser never picks the day itself.
        today_date=app_today().isoformat(),
        today=today_view,
    )


@bp.route("/log", methods=["POST"])
@require_auth
def log_progress():
    data = request.get_json(silent=True) or {}
    weight = data.get("weight")
    note = data.get("note", "")

    weight, error_key = _parse_weight(weight)
    if error_key:
        return jsonify({"error": t(error_key)}), 400
    
    
    entry = WeeklyLog(
        user_id = current_user.id,
        weight=weight,
        note=note
    )
    db.session.add(entry)
    db.session.commit()

    # Önceki kayıtlarla karşılaştırma
    previous = WeeklyLog.query.filter_by(user_id=current_user.id)\
    .order_by(WeeklyLog.created_at.desc())\
    .offset(1).first()

    message = t("route.weight_logged", weight=weight)
    if previous:
        diff = round(weight - previous.weight , 1)
        if diff < 0:
            message += t("route.weight_lost", diff=abs(diff))
        elif diff > 0:
            # D6: '=' yerine '+=' — aksi halde kilo ALMA dalında "kg kaydedildi"
            # önekı düşüyor (diğer dallar += ile ekliyor).
            message += t("route.weight_gained", diff=abs(diff))
        else:
            message += t("route.weight_same")
    return jsonify({"message" : message})


